update public.learning_paths
set
  title = 'Chemistry for Health Sciences',
  goal = 'Chemistry for Health Sciences',
  summary = 'Chemistry for Health Sciences is a general, organic, and biological chemistry course for nursing and allied-health students. It builds measurement and dose-style quantitative habits, then covers atoms, bonding, reactions, body fluids, pH and buffers, functional groups, stereochemistry, biomolecules, metabolism, clinical chemistry, and laboratory data literacy. The course keeps a nursing-focused GOB spine while adding clinical and biochemical context for later anatomy, physiology, pharmacology, pathophysiology, and nutrition.',
  data = $chsjson${"slug": "chemistry-for-health-sciences", "title": "Chemistry for Health Sciences", "description": "Chemistry for Health Sciences is a general, organic, and biological chemistry course for nursing and allied-health students. It builds measurement and dose-style quantitative habits, then covers atoms, bonding, reactions, body fluids, pH and buffers, functional groups, stereochemistry, biomolecules, metabolism, clinical chemistry, and laboratory data literacy. The course keeps a nursing-focused GOB spine while adding clinical and biochemical context for later anatomy, physiology, pharmacology, pathophysiology, and nutrition.", "topics": [{"id": "49a5c067-1fa0-43e2-bed6-e174920a29f9", "type": "topic", "title": "Matter, Measurement, and Clinical Quantitative Reasoning", "description": "Students build the measurement habits needed for safe health-science work: units, conversions, significant figures, concentrations, and dose-style reasoning.", "children": [{"id": "0fa8e1b5-df38-4252-9bbe-66551bda00d4", "type": "subtopic", "title": "Measurement and units", "description": "Health-science chemistry depends on clear measurement before interpretation.", "children": [{"id": "2c2d49bd-141d-4747-99b1-c641bef3052f", "type": "concept", "title": "SI and common clinical units"}, {"id": "628bcb74-bcf1-4577-ba9c-51b232c9b854", "type": "concept", "title": "Mass, volume, density, temperature, and pressure"}, {"id": "2db07121-d97b-4719-9ec9-e340a9953cbd", "type": "concept", "title": "Unit conversions and dimensional analysis"}]}, {"id": "3e2c7b13-9898-44d2-b4c5-2f103d19393c", "type": "subtopic", "title": "Significant figures and estimation", "description": "Students learn to judge whether a number is precise enough for the decision being made.", "children": [{"id": "e8fd082c-165c-4689-b5af-070a51ef3a97", "type": "concept", "title": "Precision versus accuracy"}, {"id": "5d9f3911-b8cf-477f-a825-ac753f465517", "type": "concept", "title": "Rounding and significant figures"}, {"id": "0f4e5033-5e88-4889-9c2d-fe67ece61b70", "type": "concept", "title": "Reasonableness checks for clinical calculations"}]}, {"id": "2c5e2d88-8b90-40b7-8cc2-1e360c8cc5c9", "type": "subtopic", "title": "Dose-style quantitative reasoning", "description": "The point is to make chemistry math feel connected to safe practice.", "children": [{"id": "a21bed2c-4d58-4c09-b088-4b5d9eea3d0e", "type": "concept", "title": "Concentration-to-amount conversions"}, {"id": "d801e692-5416-4ad8-bbe5-dae9f3dac172", "type": "concept", "title": "Dilution factors"}, {"id": "fe308244-5d9b-4625-8c97-e8f166e2d2ac", "type": "concept", "title": "Percent, ratio, molarity, and mass/volume units"}]}]}, {"id": "4c85efbe-dbd8-49f8-98c1-a64c72e7a914", "type": "topic", "title": "Atomic Structure, Ions, and the Periodic Table", "description": "This topic explains how atoms, ions, isotopes, and periodic trends help predict biologically important chemical behavior.", "children": [{"id": "52d8602f-4dbb-4db6-8a76-c55dfecb6ce8", "type": "subtopic", "title": "Atomic structure", "description": "Students learn what atoms are made of and why electron structure drives chemistry.", "children": [{"id": "87276abf-49f0-42fd-9524-f585d82de675", "type": "concept", "title": "Protons, neutrons, electrons, atomic number, and mass number"}, {"id": "d3c01ff6-f712-493e-936b-1b8b6903f3a3", "type": "concept", "title": "Isotopes and radioisotopes"}, {"id": "c8794a30-cf82-49c5-8e96-34b4aad27b0c", "type": "concept", "title": "Electron shells and valence electrons"}]}, {"id": "652ef52d-2154-491f-a961-d4cf6d3e0281", "type": "subtopic", "title": "Ions and electrolytes", "description": "Ions are central to nerve signaling, fluid balance, and clinical chemistry.", "children": [{"id": "ae5a699f-2e96-4e29-aafe-fb824cb815da", "type": "concept", "title": "Cations, anions, and ionic charge"}, {"id": "61c37a65-b8a9-47e0-a595-284409d4a65f", "type": "concept", "title": "Sodium, potassium, calcium, magnesium, chloride, bicarbonate, and phosphate"}, {"id": "db3d2cf5-f3b7-4cb6-9772-31d6ce025abb", "type": "concept", "title": "Polyatomic ions in health contexts"}]}, {"id": "68ea85ff-dc91-4566-a323-3ca46a38e1cc", "type": "subtopic", "title": "Periodic trends", "description": "The periodic table becomes a prediction tool rather than a memorization chart.", "children": [{"id": "7dac312e-bd67-486d-ad9f-5fb94092e7e7", "type": "concept", "title": "Atomic size, electronegativity, and ionization energy"}, {"id": "6caa9ca5-7ba8-46ed-af37-e8dc8707c152", "type": "concept", "title": "Metals, nonmetals, and metalloids"}, {"id": "8505bc17-2cf7-4d81-97c3-74252326b7f2", "type": "concept", "title": "Chemical families relevant to physiology and therapeutics"}]}]}, {"id": "6557ed59-e88c-4b08-a3ee-c01d8fc7e98b", "type": "topic", "title": "Chemical Bonding, Molecular Shape, and Polarity", "description": "Students learn how bonds and molecular geometry shape solubility, membrane movement, receptor binding, and intermolecular interactions.", "children": [{"id": "c6e5bfd3-a850-42a1-9994-7518e2688458", "type": "subtopic", "title": "Ionic and covalent bonding", "description": "Students learn how atoms combine and why bond type affects properties.", "children": [{"id": "7315f622-0b2a-4c83-8a61-081ede03e541", "type": "concept", "title": "Ionic compounds and salts"}, {"id": "860bc2f0-8795-4825-bdda-fbfb45de9aee", "type": "concept", "title": "Covalent bonds and molecules"}, {"id": "d3e9bf87-b404-4cd1-8c83-a8a02c7725f4", "type": "concept", "title": "Bond polarity and electronegativity"}]}, {"id": "1ba28c37-d20c-4734-930b-dac9b0d1c786", "type": "subtopic", "title": "Molecular geometry", "description": "Shape affects how molecules interact with water, proteins, and membranes.", "children": [{"id": "e734717b-66fd-4ee0-9f12-98361273c672", "type": "concept", "title": "Lewis structures and valence electrons"}, {"id": "7e0a513a-658e-4f99-b93e-20ffd3facdde", "type": "concept", "title": "VSEPR shapes"}, {"id": "ff6b7283-dd95-45eb-874e-3bc63a1e26bc", "type": "concept", "title": "Molecular polarity"}]}, {"id": "89a741e3-dc8e-48cf-b4a6-1901c0763fca", "type": "subtopic", "title": "Intermolecular forces", "description": "Weak interactions are powerful in biology because they act collectively.", "children": [{"id": "a72ac664-ba28-400d-b3a4-857da20ad207", "type": "concept", "title": "Hydrogen bonding"}, {"id": "046f2b42-2093-4a6a-9518-de503dddb8a4", "type": "concept", "title": "Dipole-dipole and London dispersion forces"}, {"id": "c1bf4aa4-0251-4f31-95d8-5e7705942401", "type": "concept", "title": "Solubility, boiling point, and biomolecular recognition"}]}]}, {"id": "44057074-9159-470f-9df6-b405a3661ea7", "type": "topic", "title": "Chemical Reactions, Stoichiometry, and Redox in Health Contexts", "description": "This module connects balanced reactions and electron transfer to oxygen transport, metabolism, disinfectants, and medication safety.", "children": [{"id": "792ebf22-92a7-4c7f-8b95-e7aa8b4b02dd", "type": "subtopic", "title": "Reaction types", "description": "Students learn to recognize what kind of chemical change is occurring.", "children": [{"id": "fe7ec83b-844c-4116-837a-06ecd135459e", "type": "concept", "title": "Synthesis, decomposition, single replacement, double replacement"}, {"id": "7f887bcd-8515-486e-a30c-39b794b15ab3", "type": "concept", "title": "Precipitation and neutralization"}, {"id": "4bb53c28-bc5b-4d4c-bc92-81420e44e617", "type": "concept", "title": "Combustion and oxidation"}]}, {"id": "ac4da385-4ef0-49d3-8a6e-91472324aeb4", "type": "subtopic", "title": "Stoichiometry", "description": "Balanced equations show how much of each substance reacts or forms.", "children": [{"id": "f576ba90-fa48-4d2f-89ad-1067980670a5", "type": "concept", "title": "Moles, molar mass, and Avogadro's number"}, {"id": "a365eaad-8ee1-4ed9-a8eb-1ca97db9f637", "type": "concept", "title": "Balanced equations and mole ratios"}, {"id": "c7649b95-815e-4b8b-b877-b4937186c206", "type": "concept", "title": "Limiting reactants and yields in simplified contexts"}]}, {"id": "99b94be8-fc38-43fa-ab29-187475cedd58", "type": "subtopic", "title": "Redox chemistry", "description": "Electron transfer connects chemistry to energy, oxygen, and oxidative stress.", "children": [{"id": "088c72a7-bd0d-4c4a-a4c9-a51210016813", "type": "concept", "title": "Oxidation and reduction"}, {"id": "fbd3cdd3-91ba-499d-8847-abdc0e24bd81", "type": "concept", "title": "Oxidizing and reducing agents"}, {"id": "0389d086-ef66-4419-bd14-70c84829ef0b", "type": "concept", "title": "Biological redox, antioxidants, disinfectants, and peroxide chemistry"}]}]}, {"id": "22ac38ad-f5ad-481a-9439-be60e2f34351", "type": "topic", "title": "Water, Solutions, Concentrations, Electrolytes, and Osmolality", "description": "Students learn the chemistry of body fluids, IV solutions, electrolyte balance, dilution, and osmotic movement.", "children": [{"id": "c8ba729b-5328-4472-bbf6-e6c84bdf1b5b", "type": "subtopic", "title": "Water chemistry", "description": "Water's polarity explains much of body-fluid chemistry.", "children": [{"id": "1325c33a-8e52-429a-b839-58c3f33ebb0d", "type": "concept", "title": "Hydrogen bonding"}, {"id": "ff99b6cc-dad1-49b0-9d02-9c8646129d05", "type": "concept", "title": "Hydrophilic and hydrophobic behavior"}, {"id": "f4710105-8a53-474b-b8e6-2e4ad4a106f2", "type": "concept", "title": "Solvation and hydration shells"}]}, {"id": "1629d06f-3ffd-46cd-968c-3fad98b6d772", "type": "subtopic", "title": "Concentration units", "description": "Students learn the units used in labs, medications, and IV fluids.", "children": [{"id": "3be31783-2a60-47d3-ad3a-1cefa869ddd7", "type": "concept", "title": "Molarity, millimoles, equivalents, and milliequivalents"}, {"id": "c5b785be-487f-492d-8948-55f45958abc9", "type": "concept", "title": "Percent solutions and mass/volume units"}, {"id": "b8cb483a-dea3-44d3-a682-67ffcc91b1dc", "type": "concept", "title": "Serial dilution and solution preparation"}]}, {"id": "b27b67bc-8545-4ee3-9691-9a4f1c076f41", "type": "subtopic", "title": "Osmosis and electrolytes", "description": "This connects chemistry to fluid shifts and patient safety.", "children": [{"id": "c570fd6d-f5e1-4e6b-a1cb-24da31515839", "type": "concept", "title": "Osmolarity and osmolality"}, {"id": "d89c8db4-dd36-4a10-ad32-70793d69bbbf", "type": "concept", "title": "Isotonic, hypotonic, and hypertonic solutions"}, {"id": "38835a59-8ee8-45e9-8b5c-d9c993607c7a", "type": "concept", "title": "Electrolyte balance and membrane movement"}]}]}, {"id": "65ec64b4-fad6-4304-a121-73e57a527433", "type": "topic", "title": "Acids, Bases, Buffers, and Physiological pH", "description": "This topic links pH, buffers, respiratory and metabolic acid-base balance, and clinical interpretation of common acid-base disturbances.", "children": [{"id": "991e5d95-eca9-45c5-8013-023ef2507fad", "type": "subtopic", "title": "Acid-base foundations", "description": "Students learn what pH measures and why small pH changes matter.", "children": [{"id": "b2b4e142-12be-4fbc-80f9-3aaa321a926a", "type": "concept", "title": "Acids, bases, conjugate pairs, and water autoionization"}, {"id": "205097fe-a26a-42b4-9d87-eeacd8de38a3", "type": "concept", "title": "pH, pOH, and logarithmic thinking"}, {"id": "d3651ac6-99d1-410b-b11e-5f2cbc3ed9ef", "type": "concept", "title": "Strong versus weak acids and bases"}]}, {"id": "eb709aa9-f9d6-411b-97e6-dd5cb4fedba6", "type": "subtopic", "title": "Buffers", "description": "Buffers stabilize pH in blood, cells, and medications.", "children": [{"id": "799dd6ec-9a08-43f1-812d-16417dd66a69", "type": "concept", "title": "Buffer components and buffer capacity"}, {"id": "a3ab6d10-3b65-4bc7-994e-d577ec7b4c48", "type": "concept", "title": "Bicarbonate, phosphate, and protein buffers"}, {"id": "0b0f1d26-fa2a-49ff-8ec8-0c60542234d2", "type": "concept", "title": "Henderson-Hasselbalch idea without overloading algebra"}]}, {"id": "d46d3076-86ff-49c5-9abe-c50122dfd553", "type": "subtopic", "title": "Clinical acid-base balance", "description": "The topic becomes useful when tied to physiology and labs.", "children": [{"id": "2ae7d7ce-c31a-4970-a32c-f654aec710e5", "type": "concept", "title": "Respiratory versus metabolic disturbances"}, {"id": "49f5d120-4aac-4fbe-a28f-adadc210ea47", "type": "concept", "title": "CO2, bicarbonate, and blood pH"}, {"id": "46e75450-29b0-4ab7-a0ac-985f4077e832", "type": "concept", "title": "Compensation and arterial blood gas reasoning at an introductory level"}]}]}, {"id": "4d4af932-389c-46f0-8152-a18e51d93c56", "type": "topic", "title": "Organic Chemistry Foundations and Functional Groups", "description": "Students learn the carbon chemistry vocabulary behind drugs, biomolecules, hormones, and metabolism.", "children": [{"id": "f2593d60-f024-4f5a-ad87-3a3702067b61", "type": "subtopic", "title": "Carbon bonding", "description": "Organic chemistry begins with carbon's bonding flexibility.", "children": [{"id": "26d3f0e0-814f-41e9-a577-5419e994d2d2", "type": "concept", "title": "Tetravalence and covalent bonding"}, {"id": "f6f40944-a618-4e6c-91d7-7ea4b4c7a010", "type": "concept", "title": "Saturated and unsaturated structures"}, {"id": "33d7c987-f307-4938-9793-80ba4099eacd", "type": "concept", "title": "Line-angle, condensed, and structural formulas"}]}, {"id": "4b111cb7-19b0-4b4c-ae7a-9b406070d1ac", "type": "subtopic", "title": "Functional groups", "description": "Functional groups predict solubility, acidity, reactivity, and biological role.", "children": [{"id": "39dc6a89-8e4e-4664-9235-db283f3c08a9", "type": "concept", "title": "Alcohols, thiols, ethers, aldehydes, ketones, carboxylic acids, esters, amines, amides"}, {"id": "c3fd9d28-08d1-4182-a35c-9807958517cf", "type": "concept", "title": "Functional groups in drugs and biomolecules"}, {"id": "421e1e58-72e0-407e-910e-0d6e7c6453ee", "type": "concept", "title": "Naming patterns used for recognition, not memorization overload"}]}, {"id": "67b7917d-90b5-4ed8-8ffc-18be1e937015", "type": "subtopic", "title": "Organic reactions", "description": "Students learn broad reaction categories rather than full synthesis.", "children": [{"id": "57df7a94-7de0-419e-b8b1-4fa84f21ce65", "type": "concept", "title": "Hydrolysis, condensation, oxidation, reduction, esterification"}, {"id": "a7b07374-31df-4196-a81d-39dd19884381", "type": "concept", "title": "Reaction sites and functional group changes"}, {"id": "ff396142-46f9-4966-84a6-062cd1a67c4c", "type": "concept", "title": "Biological reaction analogs"}]}]}, {"id": "a4a4ccd2-e9df-4b40-abdc-c0e60188ca36", "type": "topic", "title": "Structure, Stereochemistry, and Drug-Biomolecule Interactions", "description": "This module explains why molecular shape, chirality, polarity, and functional groups affect drug action and biological recognition.", "children": [{"id": "8d116686-8cd2-46ee-8759-d006bfa694ca", "type": "subtopic", "title": "Isomers", "description": "Same formula can mean different structure and different biological effect.", "children": [{"id": "dcdaa851-b96b-428d-9d2a-b59a493f2c91", "type": "concept", "title": "Structural isomers"}, {"id": "3ee30a17-38e3-4df4-a6ee-4a5f8fa078d2", "type": "concept", "title": "Geometric isomers"}, {"id": "957bc70d-cdfe-4410-b174-b928f07534df", "type": "concept", "title": "Conformational flexibility"}]}, {"id": "df9b381a-1107-4e80-8d48-647eb9d275b9", "type": "subtopic", "title": "Chirality", "description": "Handedness matters because biological targets are three-dimensional.", "children": [{"id": "94c26b8a-06ee-473e-a67d-cc1ecb16be82", "type": "concept", "title": "Chiral centers"}, {"id": "9d6906fb-81c6-4a58-8a6f-45327ccea6e0", "type": "concept", "title": "Enantiomers and diastereomers"}, {"id": "82f9e8fe-2cd2-4c8f-844e-79ff769dfd83", "type": "concept", "title": "Drug examples where stereochemistry changes activity or safety"}]}, {"id": "03d2ac97-7218-41d4-8c35-1cd0ae800601", "type": "subtopic", "title": "Molecular recognition", "description": "Students learn the chemical basis of binding.", "children": [{"id": "7ad8fe59-fe69-493f-851c-8e17c9bac3e0", "type": "concept", "title": "Shape complementarity"}, {"id": "9045113f-649a-4e2f-ae0c-a85c25f8b3af", "type": "concept", "title": "Hydrogen bonding, ionic interactions, hydrophobic effects"}, {"id": "9c6b7d29-5d64-416f-bf68-2ebbcc6ea74d", "type": "concept", "title": "Receptors, enzymes, transporters, and binding sites"}]}]}, {"id": "fa2fa22a-ac1b-4898-a647-d44bfba9e624", "type": "topic", "title": "Carbohydrates and Energy Availability", "description": "Students learn how carbohydrate structure connects to digestion, blood glucose, glycogen, and immediate energy metabolism.", "children": [{"id": "4830b668-3564-42f9-8618-f9095dc1680e", "type": "subtopic", "title": "Carbohydrate structures", "description": "Students learn how sugars are built and classified.", "children": [{"id": "16d1c3f3-d490-412b-bee6-f03561695a23", "type": "concept", "title": "Monosaccharides, disaccharides, and polysaccharides"}, {"id": "d76ab4c8-d762-4c9c-a73b-985e1a762d3f", "type": "concept", "title": "Glucose, fructose, sucrose, lactose, starch, glycogen, cellulose"}, {"id": "87d30e8b-4de0-4447-ad2e-b8b1334d020e", "type": "concept", "title": "Ring forms and glycosidic bonds"}]}, {"id": "a7964bba-8164-4a33-906f-ae5f84ce1ce7", "type": "subtopic", "title": "Digestion and blood glucose", "description": "Structure connects directly to metabolism and patient care.", "children": [{"id": "00f63823-adfa-4a20-b18b-89d51017576a", "type": "concept", "title": "Carbohydrate digestion and absorption"}, {"id": "05268c6b-a51e-4ea2-a1a4-ebac4f24524a", "type": "concept", "title": "Blood glucose regulation"}, {"id": "9dae93f3-8410-4a49-876b-74e09b5b34f6", "type": "concept", "title": "Glycogen storage and mobilization"}]}, {"id": "d97b4b35-ebeb-444b-970f-02f992ed724e", "type": "subtopic", "title": "Clinical connections", "description": "The point is to link chemistry to common health contexts.", "children": [{"id": "9e8459ff-0ea4-4b4a-8d9b-d6db5090502d", "type": "concept", "title": "Diabetes and hypoglycemia"}, {"id": "f35b4396-bfe6-4da1-bd78-4a12dc57d090", "type": "concept", "title": "Lactose intolerance"}, {"id": "ab41291a-48dc-4bba-a7d0-269723f891e9", "type": "concept", "title": "Dietary fiber and glycemic response"}]}]}, {"id": "61fdaf0a-3190-48b0-ab59-cf2ab7bad7a3", "type": "topic", "title": "Lipids, Membranes, and Lipid Metabolism", "description": "This topic connects lipid chemistry to membranes, transport, energy storage, hormones, and cardiometabolic health.", "children": [{"id": "fd7e110d-833b-4e25-b762-f72e218eb4e1", "type": "subtopic", "title": "Lipid classes", "description": "Students learn why lipids are chemically diverse but often hydrophobic.", "children": [{"id": "9bc903c9-42ce-4d03-9cf5-79bdbe60ae55", "type": "concept", "title": "Fatty acids, triglycerides, phospholipids, steroids, and eicosanoids"}, {"id": "c3da93f1-98e6-49f9-a66f-0c496d747860", "type": "concept", "title": "Saturated, unsaturated, cis, and trans fats"}, {"id": "712fc060-81e4-4926-be00-4f761bae5885", "type": "concept", "title": "Essential fatty acids"}]}, {"id": "96fb97ff-3634-4a27-a640-70287d72a62f", "type": "subtopic", "title": "Membranes and transport", "description": "Lipid chemistry explains barriers and selective movement.", "children": [{"id": "b302f611-6aba-4eaf-a641-fa15fe368ed3", "type": "concept", "title": "Phospholipid bilayers"}, {"id": "741a8132-a5af-45c9-a8f5-4e4898147f8c", "type": "concept", "title": "Membrane proteins and channels"}, {"id": "eadc5e93-ac17-48f9-9a26-d9eead769c40", "type": "concept", "title": "Lipid solubility and drug distribution"}]}, {"id": "c93b935f-16e3-44d7-8a98-c1cdf9d9d9bd", "type": "subtopic", "title": "Lipid metabolism and health", "description": "Students connect lipid chemistry to energy and disease risk.", "children": [{"id": "91b08fc1-1b4b-4e30-8b6f-2371a870d95f", "type": "concept", "title": "Beta-oxidation overview"}, {"id": "b89d38a2-26cd-4c84-8db5-80187adb65b2", "type": "concept", "title": "Cholesterol and lipoproteins"}, {"id": "925f8727-86c9-4c16-8d1b-80fcdb71ce99", "type": "concept", "title": "Ketone bodies and cardiometabolic markers"}]}]}, {"id": "d0458b52-19b0-4893-94e2-4a5ddae1e6f2", "type": "topic", "title": "Amino Acids, Proteins, Enzymes, and Clinical Catalysis", "description": "Students learn how proteins provide structure, transport, immunity, movement, and catalysis, and how enzymes are regulated or inhibited.", "children": [{"id": "ba1cf12d-4015-4daa-b46a-e68451377fdc", "type": "subtopic", "title": "Amino acids and protein structure", "description": "Students learn how protein structure emerges from amino acid chemistry.", "children": [{"id": "23cf5606-e07a-46ba-9266-18b0d9333226", "type": "concept", "title": "Side-chain polarity and charge"}, {"id": "9df65ebf-10d0-41bf-a57d-b71f886b2071", "type": "concept", "title": "Peptide bonds"}, {"id": "73ca25ff-9de7-470f-ad1a-9c50c5d5001b", "type": "concept", "title": "Primary, secondary, tertiary, and quaternary structure"}]}, {"id": "78b71961-040f-47f5-8ea9-a2e2f371ff8c", "type": "subtopic", "title": "Protein function", "description": "Proteins perform most cellular work.", "children": [{"id": "cedeb925-2bf6-42a0-873e-1f33608fe274", "type": "concept", "title": "Transport, structure, signaling, immunity, movement, and clotting"}, {"id": "5968719b-9a14-407a-95c0-653b63675e73", "type": "concept", "title": "Hemoglobin and oxygen binding"}, {"id": "e0ee15e1-91d7-4973-b059-27e697690d25", "type": "concept", "title": "Denaturation and protein misfolding"}]}, {"id": "602bcd22-460b-4863-9c51-72955e990262", "type": "subtopic", "title": "Enzymes", "description": "Enzymes make biological chemistry fast and regulated.", "children": [{"id": "cad7332e-2529-4709-8893-c5b405a08236", "type": "concept", "title": "Active sites and specificity"}, {"id": "94fef39b-28bc-475f-b6fa-bd601831e268", "type": "concept", "title": "Michaelis-Menten ideas at a conceptual level"}, {"id": "b7ce9af8-8eeb-